'use client';

import { deleteDashboard } from '@app/entities/dashboard';
import { useWidgetStore } from '@app/entities/widget/store';
import { Button } from '@packages/ui/Button';
import { Dialog } from '@packages/ui/Dialog';
import { toast } from '@packages/ui/Toast';
import React, { useState } from 'react';

export function DeleteDashboardDialog({
  dashboardId,
  dashboardName,
  open,
  onOpenChange,
  onDeleted,
}: {
  dashboardId: string;
  dashboardName: string;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onDeleted: () => void;
}) {
  const [deleting, setDeleting] = useState(false);
  const [error, setError] = useState<string | undefined>();

  const handleDelete = async () => {
    setDeleting(true);
    setError(undefined);
    try {
      await deleteDashboard(dashboardId);
      // also remove widgets
      useWidgetStore.setState(({ records }) => ({
        records: records.filter((w) => w.dashboard !== dashboardId),
      }));
      toast({ title: 'Dashboard deleted' });
      onOpenChange(false);
      onDeleted();
    } catch {
      setError('Could not delete. Try again.');
    } finally {
      setDeleting(false);
    }
  };

  return (
    <Dialog
      title="Delete this dashboard?"
      open={open}
      onOpenChange={onOpenChange}
      footer={(close) => (
        <>
          <Button onClick={() => close()}>
            Cancel
          </Button>
          <Button
            // destructive confirm for permanent delete
            variant="danger"
            loading={deleting}
            onClick={handleDelete}
          >
            Delete
          </Button>
        </>
      )}
    >
      <p>This will permanently delete the dashboard and all its widgets. This cannot be undone.</p>
      {error ? <p role="alert">{error}</p> : null}
    </Dialog>
  );
}

