import { createWidget } from '../widget/operations';
import { useWidgetStore } from '../widget/store';

import { duplicateDashboard } from './operations';

import type { DashboardInput } from './types';

/**
 * Duplicates a dashboard and all its widgets via entity operations.
 * Each widget is recreated through createWidget so the screen never touches the store directly.
 */
export async function duplicateDashboardWithWidgets(
  dashboardId: string,
  dashboardName: string,
) {
  const copy = await duplicateDashboard({ name: `${dashboardName} Copy`, lastEditedAt: new Date().toISOString() } as DashboardInput);
  const widgets = useWidgetStore.getState().records.filter((w) => w.dashboard === dashboardId);
  for (const w of widgets) {
    const { id: _id, createdAt: _c, updatedAt: _u, ...rest } = w;
    await createWidget({ ...rest, dashboard: copy.id } as never);
  }
  return copy;
}

