'use client';

import { changePassword } from '@app/entities/auth';
import { useCurrentUser } from '@app/entities/auth';
import { PageHeader } from '@app/components/PageHeader';
import { Button } from '@packages/ui/Button';
import { Form } from '@packages/ui/Form';
import { Controller } from '@packages/ui/Form';
import { PasswordInput } from '@packages/ui/Input';
import { Section } from '@packages/ui/Section';
import { DescriptionDetails, DescriptionList, DescriptionTerm } from '@packages/ui/Typography';
import { toast } from '@packages/ui/Toast';
import React, { useState } from 'react';
import { useForm } from 'react-hook-form';

type FormValues = { currentPassword: string; newPassword: string };

export default function AccountPage() {
  const user = useCurrentUser();
  const [formError, setFormError] = useState<string | undefined>();
  const [saving, setSaving] = useState(false);
  const { control, handleSubmit, reset } = useForm<FormValues>({
    defaultValues: { currentPassword: '', newPassword: '' },
  });

  const onSubmit = async (values: FormValues) => {
    if (saving) return;
    setFormError(undefined);
    if (!values.currentPassword || values.newPassword.length < 8 || values.newPassword.length > 128) {
      setFormError('Current password is required and new password must be 8 to 128 characters');
      reset({ currentPassword: '', newPassword: '' });
      return;
    }
    setSaving(true);
    try {
      await changePassword(values.currentPassword, values.newPassword);
      toast({ title: 'Password changed' });
      reset({ currentPassword: '', newPassword: '' });
    } catch (err: unknown) {
      const msg = (err as Error).message;
      if ((err as { code?: string }).code === 'incorrect' || msg === 'Current password is incorrect.') {
        setFormError('Current password is incorrect.');
      } else if (msg.includes('required and new password')) {
        setFormError(msg);
      } else {
        setFormError('Could not update password. Try again.');
      }
      reset({ currentPassword: '', newPassword: '' });
    } finally {
      setSaving(false);
    }
  };

  return (
    <>
      <PageHeader title="Account" />
      <Section title="Your account">
        <DescriptionList>
          <DescriptionTerm>Email</DescriptionTerm>
          <DescriptionDetails>{user && typeof user === 'object' ? (user as { email: string }).email : ''}</DescriptionDetails>
        </DescriptionList>
      </Section>
      <Section title="Change password">
        <Form
          error={formError}
          onSubmit={handleSubmit(onSubmit)}
          actions={
            <Button type="submit" loading={saving} loadingWithReason="Saving password">
              Save
            </Button>
          }
        >
          <Controller
            name="currentPassword"
            control={control}
            rules={{ required: 'Current password is required and new password must be 8 to 128 characters' }}
          >
            {({ field }) => <PasswordInput label="Current password" autoComplete="current-password" {...field} />}
          </Controller>
          <Controller
            name="newPassword"
            control={control}
            rules={{ required: 'Current password is required and new password must be 8 to 128 characters' }}
          >
            {({ field }) => <PasswordInput label="New password" autoComplete="new-password" {...field} />}
          </Controller>
        </Form>
      </Section>
    </>
  );
}

'use client';

import { deleteDashboard } from '@app/entities/dashboard';
import { useWidgetStore } from '@app/entities/widget/store';
import { Button } from '@packages/ui/Button';
import { Dialog } from '@packages/ui/Dialog';
import { toast } from '@packages/ui/Toast';
import React, { useState } from 'react';

export function DeleteDashboardDialog({
  dashboardId,
  dashboardName,
  open,
  onOpenChange,
  onDeleted,
}: {
  dashboardId: string;
  dashboardName: string;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onDeleted: () => void;
}) {
  const [deleting, setDeleting] = useState(false);
  const [error, setError] = useState<string | undefined>();

  const handleDelete = async () => {
    if (deleting) return;
    setDeleting(true);
    setError(undefined);
    try {
      await deleteDashboard(dashboardId);
      // Remove orphaned widgets via store - widget has no bulk delete operation
      // This is the only store access: dashboard deletion must clean up child widgets
      useWidgetStore.setState(({ records }) => ({
        records: records.filter((w) => w.dashboard !== dashboardId),
      }));
      toast({ title: 'Dashboard deleted' });
      onOpenChange(false);
      onDeleted();
    } catch {
      setError('Could not delete. Try again.');
    } finally {
      setDeleting(false);
    }
  };

  return (
    <Dialog
      title="Delete this dashboard?"
      open={open}
      onOpenChange={onOpenChange}
      footer={(close) => (
        <>
          <Button onClick={() => close()}>Cancel</Button>
          <Button
            // destructive confirm for permanent delete
            variant="danger"
            loading={deleting}
            loadingWithReason="Deleting dashboard"
            onClick={handleDelete}
          >
            Delete
          </Button>
        </>
      )}
    >
      <p>This will permanently delete the dashboard and all its widgets. This cannot be undone.</p>
      {error ? <p role="alert">{error}</p> : null}
    </Dialog>
  );
}

'use client';

import { createDashboard, updateDashboard, useListDashboards } from '@app/entities/dashboard';
import { duplicateDashboardWithWidgets } from '@app/entities/dashboard/duplicateWithWidgets';
import { PageHeader } from '@app/components/PageHeader';
import { NextLink } from '@app/components/NextLink';
import { DeleteDashboardDialog } from '@app/blocks/DeleteDashboardDialog';
import { Button, IconButton } from '@packages/ui/Button';
import { Dropdown } from '@packages/ui/Dropdown';
import { Input, SearchInput } from '@packages/ui/Input';
import { createTable } from '@packages/ui/Table';
import { Tooltip } from '@packages/ui/Tooltip';
import { Time } from '@packages/ui/Typography';
import { toast } from '@packages/ui/Toast';
import { Check, EllipsisVertical, Pencil, X } from 'lucide-react';
import { useRouter } from 'next/navigation';
import React, { useMemo, useState } from 'react';

import type { Dashboard } from '@app/entities/dashboard/types';

const DashTable = createTable<Dashboard>();

export default function DashboardsPage() {
  const { data: dashboards, loading, error, retry } = useListDashboards();
  const router = useRouter();
  const [search, setSearch] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');
  const [editError, setEditError] = useState<string | undefined>();
  const [saving, setSaving] = useState(false);
  const [pendingId, setPendingId] = useState<string | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<Dashboard | null>(null);

  const sorted = useMemo(() => {
    if (!dashboards) return [];
    return [...dashboards].sort((a, b) => new Date(b.lastEditedAt).getTime() - new Date(a.lastEditedAt).getTime());
  }, [dashboards]);

  const filtered = useMemo(() => {
    if (!search.trim()) return sorted;
    const q = search.toLowerCase();
    return sorted.filter((d) => d.name.toLowerCase().includes(q));
  }, [sorted, search]);

  const isEmpty = !loading && !error && sorted.length === 0;
  const noResults = !loading && !error && sorted.length > 0 && filtered.length === 0;

  const handleCreate = async () => {
    if (pendingId) return;
    setPendingId('create');
    try {
      const base = 'Untitled Dashboard';
      let name = base;
      let n = 2;
      const names = new Set(sorted.map((r) => r.name));
      while (names.has(name)) { name = `${base} ${n}`; n += 1; }
      const d = await createDashboard({ name, lastEditedAt: new Date().toISOString() });
      router.push(`/dashboards/${d.id}`);
    } catch {
      toast({ title: 'Could not create dashboard. Try again.', status: 'error' });
    } finally { setPendingId(null); }
  };

  const startEdit = (d: Dashboard) => { setEditingId(d.id); setEditName(d.name); setEditError(undefined); };
  const cancelEdit = () => { setEditingId(null); setEditName(''); setEditError(undefined); };
  const saveEdit = async (d: Dashboard) => {
    if (saving) return;
    if (!editName.trim() || editName.length > 80) { setEditError('Name is required and max 80 characters'); return; }
    setSaving(true);
    try {
      await updateDashboard(d.id, { name: editName, lastEditedAt: new Date().toISOString() });
      toast({ title: 'Dashboard saved' });
      setEditingId(null);
    } catch { setEditError('Could not save. Try again.'); } finally { setSaving(false); }
  };
  const handleDuplicate = async (d: Dashboard) => {
    if (pendingId) return;
    setPendingId(d.id);
    try {
      const copy = await duplicateDashboardWithWidgets(d.id, d.name);
      toast({ title: 'Dashboard duplicated' });
      router.push(`/dashboards/${copy.id}`);
    } catch { toast({ title: 'Could not duplicate. Try again.', status: 'error' }); } finally { setPendingId(null); }
  };

  if (loading) return <PageHeader title="Your dashboards" />;
  if (error) return <><PageHeader title="Your dashboards" /><p role="alert">Failed to load. </p><Button onClick={retry}>Retry</Button></>;
  if (isEmpty) {
    return (
      <>
        <PageHeader title="Your dashboards" />
        <div data-ds="" className="flex-col-gap-4 items-start">
          <p>No dashboards yet. Create your first dashboard to start your console.</p>
          <Button onClick={handleCreate} loading={pendingId === 'create'} loadingWithReason="Creating dashboard">Create dashboard</Button>
        </div>
      </>
    );
  }

  return (
    <>
      <PageHeader title="Your dashboards" />
      <div data-ds="" className="flex-col-gap-4">
        <div data-ds="" className="flex-row-gap-3 items-center">
          <SearchInput label="Search" value={search} onChange={setSearch} />
        </div>
        {noResults ? (
          <div data-ds="" className="flex-col-gap-3 items-start">
            <p>No results for your search. Try another name.</p>
            <Button onClick={() => setSearch('')}>Clear search</Button>
          </div>
        ) : (
          <DashTable data={filtered} rowKey={(d) => d.id} caption="Your dashboards" onRowClick={(d) => router.push(`/dashboards/${d.id}`)}>
            <DashTable.Column id="name" rowHeader title="Name" dataKey="name" width={300}>
              {(name: string, d: Dashboard) =>
                editingId === d.id ? (
                  <span className="flex-row-gap-2 items-center">
                    <Input aria-label="Dashboard name" value={editName} onChange={setEditName} autoComplete="off" error={editError} />
                    <IconButton tooltip="Save" onClick={() => saveEdit(d)} loading={saving} loadingWithReason="Saving">
                      <Check />
                    </IconButton>
                    <IconButton tooltip="Cancel" onClick={cancelEdit}><X /></IconButton>
                  </span>
                ) : (
                  <span className="flex-row-gap-2 items-center">
                    <NextLink href={`/dashboards/${d.id}`}>{name}</NextLink>
                    <IconButton tooltip="Rename" onClick={(e: React.MouseEvent) => { e.stopPropagation(); startEdit(d); }}><Pencil /></IconButton>
                  </span>
                )
              }
            </DashTable.Column>
            <DashTable.Column id="lastEditedAt" title="Last edited" dataKey="lastEditedAt" width={200}>
              {(val: string) => (
                <Tooltip tooltip={new Date(val).toLocaleString()}>
                  <Time value={val} />
                </Tooltip>
              )}
            </DashTable.Column>
            <DashTable.Column id="actions" title="" width={80}>
              {(_: unknown, d: Dashboard) => (
                <Dropdown menu={<><Dropdown.Item onSelect={() => handleDuplicate(d)}>Duplicate</Dropdown.Item><Dropdown.Item onSelect={() => setDeleteTarget(d)}>Delete</Dropdown.Item></>}>
                  <IconButton tooltip="More actions" loading={pendingId === d.id} loadingWithReason="Duplicating"><EllipsisVertical /></IconButton>
                </Dropdown>
              )}
            </DashTable.Column>
          </DashTable>
        )}
      </div>
      {deleteTarget ? <DeleteDashboardDialog dashboardId={deleteTarget.id} dashboardName={deleteTarget.name} open={!!deleteTarget} onOpenChange={(o) => !o && setDeleteTarget(null)} onDeleted={() => setDeleteTarget(null)} /> : null}
    </>
  );
}

