'use client';

import { updateDashboard } from '@app/entities/dashboard';
import { updateNoteText } from '@app/entities/widget';
import { Textarea } from '@packages/ui/Textarea';
import { toast } from '@packages/ui/Toast';
import React, { useState } from 'react';

import type { Widget } from '@app/entities/widget/types';

export function NoteWidget({ widget, dashboardId, onSaved }: { widget: Widget; dashboardId: string; onSaved: () => void }) {
  const [error, setError] = useState<string | undefined>();
  const [pending, setPending] = useState(false);
  return (
    <div data-ds="" className="flex-col-gap-2">
      <Textarea
        label="Note"
        value={widget.noteText || ''}
        onChange={async (v) => {
          if (pending) return;
          if (v.length > 5000) { setError('Max 5000 characters'); return; }
          setError(undefined);
          setPending(true);
          try { await updateNoteText(widget.id, { noteText: v } as never); await updateDashboard(dashboardId, { lastEditedAt: new Date().toISOString() }); onSaved(); } catch { toast({ title: 'Saving failed. Try again.', status: 'error' }); } finally { setPending(false); }
        }}
        error={error}
      />
    </div>
  );
}

'use client';

import { updateDashboard } from '@app/entities/dashboard';
import { incrementCounter, updateCounterLabel } from '@app/entities/widget';
import { IconButton } from '@packages/ui/Button';
import { Input } from '@packages/ui/Input';
import { Numeral } from '@packages/ui/Numeral';
import { toast } from '@packages/ui/Toast';
import { Check, Minus, Pencil, Plus, X } from 'lucide-react';
import React, { useState } from 'react';

import type { Widget } from '@app/entities/widget/types';

export function CounterWidget({ widget, dashboardId, onSaved }: { widget: Widget; dashboardId: string; onSaved: () => void }) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState('');
  const [error, setError] = useState<string | undefined>();
  const [pending, setPending] = useState(false);

  const change = async (delta: number) => {
    if (pending) return;
    setPending(true);
    try { await incrementCounter(widget.id, { counterValue: (widget.counterValue ?? 0) + delta } as never); await updateDashboard(dashboardId, { lastEditedAt: new Date().toISOString() }); onSaved(); } catch { toast({ title: 'Saving failed. Try again.', status: 'error' }); } finally { setPending(false); }
  };

  return (
    <div data-ds="" className="flex-col-gap-3">
      {editing ? (
        <span className="flex-row-gap-2 items-center">
          <Input aria-label="Counter label" value={draft} onChange={setDraft} autoComplete="off" error={error} />
          <IconButton tooltip="Save" onClick={async () => {
            if (draft.length > 40) { setError('Max 40 characters'); return; }
            setError(undefined);
            try { await updateCounterLabel(widget.id, { counterLabel: draft } as never); onSaved(); setEditing(false); } catch { toast({ title: 'Saving failed. Try again.', status: 'error' }); }
          }}><Check /></IconButton>
          <IconButton tooltip="Cancel" onClick={() => setEditing(false)}><X /></IconButton>
        </span>
      ) : (
        <span className="flex-row-gap-2 items-center">
          <span>{widget.counterLabel || 'Count'}</span>
          <IconButton tooltip="Edit label" onClick={() => { setEditing(true); setDraft(widget.counterLabel || ''); setError(undefined); }}><Pencil /></IconButton>
        </span>
      )}
      <div data-ds="" className="flex-row-gap-3 items-center">
        <IconButton tooltip="Decrease" onClick={() => change(-1)} loading={pending} loadingWithReason="Saving"><Minus /></IconButton>
        <Numeral>{widget.counterValue ?? 0}</Numeral>
        <IconButton tooltip="Increase" onClick={() => change(1)} loading={pending} loadingWithReason="Saving"><Plus /></IconButton>
      </div>
    </div>
  );
}

'use client';

import { addChecklistItem, removeChecklistItem, toggleChecklistItem, updateChecklistItem } from '@app/entities/widget';
import { Button, IconButton } from '@packages/ui/Button';
import { Checkbox } from '@packages/ui/Checkbox';
import { Input } from '@packages/ui/Input';
import { toast } from '@packages/ui/Toast';
import { Check, Pencil, Trash2, X } from 'lucide-react';
import React, { useState } from 'react';

import type { Widget } from '@app/entities/widget/types';

export function ChecklistWidget({ widget, onSaved }: { widget: Widget; onSaved: () => void }) {
  const [newItem, setNewItem] = useState('');
  const [newError, setNewError] = useState<string | undefined>();
  const [editIdx, setEditIdx] = useState<number | null>(null);
  const [draft, setDraft] = useState('');
  const [editError, setEditError] = useState<string | undefined>();
  const [pending, setPending] = useState(false);

  return (
    <div data-ds="" className="flex-col-gap-3">
      {(widget.checklistItemText || []).map((text, idx) => (
        // Key uses text + index as stable as available; checklist items have no id in model
        <div key={`${widget.id}-item-${idx}-${text}`} data-ds="" className="flex-row-gap-2 items-center">
          <Checkbox checked={widget.checklistChecked?.[idx] ?? false} onCheckedChange={(c) => {
            if (pending) return;
            const next = [...(widget.checklistChecked || [])];
            (next as boolean[])[idx] = c;
            setPending(true);
            toggleChecklistItem(widget.id, { checklistChecked: next } as never).then(() => onSaved()).catch(() => toast({ title: 'Saving failed. Try again.', status: 'error' })).finally(() => setPending(false));
          }} value={text} aria-label={text} />
          {editIdx === idx ? (
            <>
              <Input aria-label="Checklist item text" value={draft} onChange={setDraft} autoComplete="off" error={editError} />
              <IconButton tooltip="Save" onClick={async () => {
                if (!draft.trim() || draft.length > 120) { setEditError('Text is required and max 120 characters'); return; }
                setEditError(undefined);
                if (pending) return; setPending(true);
                const nt = [...(widget.checklistItemText || [])]; nt[idx] = draft;
                try { await updateChecklistItem(widget.id, { checklistItemText: nt } as never); onSaved(); setEditIdx(null); } catch { toast({ title: 'Saving failed. Try again.', status: 'error' }); } finally { setPending(false); }
              }}><Check /></IconButton>
              <IconButton tooltip="Cancel" onClick={() => setEditIdx(null)}><X /></IconButton>
            </>
          ) : (
            <>
              <span>{text}</span>
              <IconButton tooltip="Edit" onClick={() => { setEditIdx(idx); setDraft(text); setEditError(undefined); }}><Pencil /></IconButton>
              <IconButton tooltip="Remove" onClick={async () => {
                if (pending) return; setPending(true);
                const nt = (widget.checklistItemText || []).filter((_, i) => i !== idx);
                const nc = (widget.checklistChecked || []).filter((_, i) => i !== idx);
                try { await removeChecklistItem(widget.id, { checklistItemText: nt, checklistChecked: nc } as never); onSaved(); } catch { toast({ title: 'Saving failed. Try again.', status: 'error' }); } finally { setPending(false); }
              }}><Trash2 /></IconButton>
            </>
          )}
        </div>
      ))}
      <span className="flex-row-gap-2 items-center">
        <Input aria-label="New checklist item" value={newItem} onChange={setNewItem} autoComplete="off" error={newError} />
        <Button onClick={async () => {
          const v = newItem.trim(); if (!v || v.length > 120) { setNewError('Text is required and max 120 characters'); return; }
          setNewError(undefined);
          if (pending) return; setPending(true);
          try { await addChecklistItem(widget.id, { checklistItemText: [...(widget.checklistItemText || []), v], checklistChecked: [...(widget.checklistChecked || []), false] } as never); setNewItem(''); onSaved(); } catch { toast({ title: 'Saving failed. Try again.', status: 'error' }); } finally { setPending(false); }
        }}>Add</Button>
      </span>
    </div>
  );
}

'use client';

import { removeLink } from '@app/entities/widget';
import { Button, IconButton } from '@packages/ui/Button';
import { Link } from '@packages/ui/Link';
import { toast } from '@packages/ui/Toast';
import { Pencil, Trash2 } from 'lucide-react';
import React, { useState } from 'react';

import type { Widget } from '@app/entities/widget/types';

function isSafeUrl(url: string): boolean {
  return /^https?:\/\//.test(url);
}

export function LinkListWidget({ widget, onAdd, onEdit }: { widget: Widget; onAdd: () => void; onEdit: (idx: number) => void }) {
  const [pendingIdx, setPendingIdx] = useState<number | null>(null);
  return (
    <div data-ds="" className="flex-col-gap-3">
      {(widget.linkTitle || []).map((title, idx) => {
        const url = widget.linkUrl?.[idx] || '';
        return (
          <div key={`${widget.id}-link-${idx}-${title}`} data-ds="" className="flex-row-gap-2 items-center">
            {isSafeUrl(url) ? <Link href={url} target="_blank" rel="noreferrer">{title}</Link> : <span>{title}</span>}
            <IconButton tooltip="Edit link" onClick={() => onEdit(idx)}><Pencil /></IconButton>
            <IconButton tooltip="Remove link" loading={pendingIdx === idx} loadingWithReason="Removing" onClick={async () => {
              if (pendingIdx !== null) return; setPendingIdx(idx);
              const nt = (widget.linkTitle || []).filter((_, i) => i !== idx);
              const nu = (widget.linkUrl || []).filter((_, i) => i !== idx);
              try { await removeLink(widget.id, { linkTitle: nt, linkUrl: nu } as never); } catch { toast({ title: 'Saving failed. Try again.', status: 'error' }); } finally { setPendingIdx(null); }
            }}><Trash2 /></IconButton>
          </div>
        );
      })}
      <Button onClick={onAdd}>Add link</Button>
    </div>
  );
}

'use client';

import { DeleteDashboardDialog } from '@app/blocks/DeleteDashboardDialog';
import { NotFound } from '@app/components/NotFound';
import { PageHeader } from '@app/components/PageHeader';
import { duplicateDashboardWithWidgets } from '@app/entities/dashboard/duplicateWithWidgets';
import { useGetDashboard, updateDashboard } from '@app/entities/dashboard';
import { addLink, createWidget, deleteWidget, removeLink, repositionWidget, updateLink, updateWidgetTitle, useListWidgets } from '@app/entities/widget';
import { Button, IconButton } from '@packages/ui/Button';
import { Card } from '@packages/ui/Card';
import { CardList } from '@packages/ui/Card';
import { Dialog } from '@packages/ui/Dialog';
import { Dropdown } from '@packages/ui/Dropdown';
import { Input } from '@packages/ui/Input';
import { Select, SelectOption } from '@packages/ui/Select';
import { toast } from '@packages/ui/Toast';
import { Check, ChevronDown, ChevronUp, Pencil, Settings, Trash2, X } from 'lucide-react';
import { useParams, useRouter } from 'next/navigation';
import React, { useEffect, useMemo, useRef, useState } from 'react';

import { ChecklistWidget } from './components/ChecklistWidget';
import { CounterWidget } from './components/CounterWidget';
import { LinkListWidget } from './components/LinkListWidget';
import { NoteWidget } from './components/NoteWidget';

import type { Widget } from '@app/entities/widget/types';

const sizeSpan: Record<string, string> = { small: 'span 4', medium: 'span 6', large: 'span 12' };

export default function DashboardDetailPage() {
  const params = useParams<{ dashboardId: string }>();
  const dashboardId = params.dashboardId;
  const { data: dashboard, loading: dashLoading, error: dashError, retry } = useGetDashboard(dashboardId);
  const { data: allWidgets, loading: wLoading } = useListWidgets();
  const router = useRouter();

  const [editing, setEditing] = useState(false);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const timer2Ref = useRef<ReturnType<typeof setTimeout> | null>(null);
  useEffect(() => () => { if (timerRef.current) clearTimeout(timerRef.current); if (timer2Ref.current) clearTimeout(timer2Ref.current); }, []);

  const flash = () => {
    setSaving(true);
    if (timerRef.current) clearTimeout(timerRef.current);
    timerRef.current = setTimeout(() => {
      setSaving(false); setSaved(true);
      timer2Ref.current = setTimeout(() => setSaved(false), 1500);
    }, 300);
  };

  const [dashName, setDashName] = useState('');
  const [dashErr, setDashErr] = useState<string | undefined>();
  const [showDelete, setShowDelete] = useState(false);
  const [showAdd, setShowAdd] = useState(false);
  const [nType, setNType] = useState('note');
  const [nTitle, setNTitle] = useState('');
  const [nSize, setNSize] = useState('medium');
  const [nErr, setNErr] = useState<string | undefined>();
  const [nPending, setNPending] = useState(false);
  const [remId, setRemId] = useState<string | null>(null);
  const [remPending, setRemPending] = useState(false);
  const [editLinkW, setEditLinkW] = useState<Widget | null>(null);
  const [editLinkIdx, setEditLinkIdx] = useState<number | null>(null);
  const [lTitle, setLTitle] = useState('');
  const [lUrl, setLUrl] = useState('');
  const [lErr, setLErr] = useState<string | undefined>();
  const [lPending, setLPending] = useState(false);
  const [editWTitle, setEditWTitle] = useState<string | null>(null);
  const [wTitleDraft, setWTitleDraft] = useState('');
  const [wTitleErr, setWTitleErr] = useState<string | undefined>();
  const [dupPending, setDupPending] = useState(false);

  const widgets = useMemo(() => {
    if (!allWidgets) return [];
    return allWidgets.filter((w) => w.dashboard === dashboardId).sort((a, b) => a.position - b.position);
  }, [allWidgets, dashboardId]);

  if (dashLoading || wLoading) return <PageHeader title="Loading" />;
  if (dashError) return <><PageHeader title="Error" /><p role="alert">Failed to load</p><Button onClick={retry}>Retry</Button></>;
  if (!dashboard) return <NotFound title="Dashboard not found" description="This dashboard is gone." back={{ label: 'Go to your dashboards', href: '/dashboards' }} />;

  const handleSaveDash = async () => {
    if (!dashName.trim() || dashName.length > 80) { setDashErr('Name is required and max 80 characters'); return; }
    try { await updateDashboard(dashboard.id, { name: dashName, lastEditedAt: new Date().toISOString() }); toast({ title: 'Dashboard saved' }); flash(); } catch { setDashErr('Could not save. Try again.'); }
  };
  const handleDup = async () => {
    if (dupPending) return; setDupPending(true);
    try { const copy = await duplicateDashboardWithWidgets(dashboard.id, dashboard.name); router.push(`/dashboards/${copy.id}`); } catch { toast({ title: 'Could not duplicate. Try again.', status: 'error' }); } finally { setDupPending(false); }
  };
  const handleCreate = async () => {
    if (nPending) return;
    if (!nType) { setNErr('Title max 60 characters and type is required'); return; }
    if (nTitle.length > 60) { setNErr('Title max 60 characters and type is required'); return; }
    setNPending(true);
    try {
      const title = nTitle || nType.charAt(0).toUpperCase() + nType.slice(1);
      await createWidget({ title, type: nType as Widget['type'], size: nSize as Widget['size'], position: widgets.length + 1, dashboard: dashboardId, noteText: '', counterLabel: '', counterValue: 0, checklistItemText: [], checklistChecked: [], linkTitle: [], linkUrl: [] } as never);
      await updateDashboard(dashboardId, { lastEditedAt: new Date().toISOString() }); flash(); toast({ title: 'Widget created' }); setShowAdd(false); setNTitle(''); setNErr(undefined);
    } catch { setNErr('Could not create widget. Try again.'); } finally { setNPending(false); }
  };
  const handleRemoveW = async () => {
    if (!remId || remPending) return; setRemPending(true);
    try { await deleteWidget(remId); await updateDashboard(dashboardId, { lastEditedAt: new Date().toISOString() }); flash(); toast({ title: 'Widget removed' }); setRemId(null); } catch { toast({ title: 'Could not remove widget. Try again.', status: 'error' }); } finally { setRemPending(false); }
  };
  const handleWTitle = async (w: Widget) => {
    if (wTitleDraft.length > 60) { setWTitleErr('Max 60 characters'); return; }
    try { await updateWidgetTitle(w.id, { title: wTitleDraft } as never); await updateDashboard(dashboardId, { lastEditedAt: new Date().toISOString() }); flash(); setEditWTitle(null); setWTitleErr(undefined); } catch { setWTitleErr('Saving failed. Try again.'); }
  };
  const handleMove = async (w: Widget, dir: number) => {
    const idx = widgets.findIndex((x) => x.id === w.id); const ni = idx + dir; if (ni < 0 || ni >= widgets.length) return;
    const other = widgets[ni];
    const origW = w.position; const origO = other.position;
    try { await repositionWidget(w.id, { position: origO } as never); await repositionWidget(other.id, { position: origW } as never); await updateDashboard(dashboardId, { lastEditedAt: new Date().toISOString() }); flash(); } catch {
      // Rollback: try to restore positions
      try { await repositionWidget(w.id, { position: origW } as never); await repositionWidget(other.id, { position: origO } as never); } catch { /* rollback failed */ }
      toast({ title: 'Could not reorder. Try again.', status: 'error' });
    }
  };

  return (
    <>
      <PageHeader
        title={
          <span className="flex-row-gap-2 items-center">
            <span>{dashboard.name}</span>
            <span aria-live="polite" className="text-sm opacity-60">{saving ? 'Saving' : saved ? 'Saved' : ''}</span>
          </span>
        }
        breadcrumb={[{ label: 'Back to dashboards', href: '/dashboards' }]}
        actions={
          editing ? (
            <>
              <Button onClick={() => setShowAdd(true)}>Add widget</Button>
              <Dropdown menu={<><Dropdown.Item onSelect={handleDup}>Duplicate</Dropdown.Item><Dropdown.Item onSelect={() => setShowDelete(true)}>Delete</Dropdown.Item></>}>
                <Button variant="base">More</Button>
              </Dropdown>
              <Button onClick={() => setEditing(false)}>Done</Button>
            </>
          ) : (
            <Button onClick={() => { setEditing(true); setDashName(dashboard.name); setDashErr(undefined); }}>Edit</Button>
          )
        }
      />
      {editing ? (
        <div data-ds="" className="flex-row-gap-2 items-center">
          <Input aria-label="Dashboard name" value={dashName} onChange={setDashName} autoComplete="off" error={dashErr} />
          <IconButton tooltip="Save" onClick={handleSaveDash}><Check /></IconButton>
          <IconButton tooltip="Cancel" onClick={() => setDashName(dashboard.name)}><X /></IconButton>
        </div>
      ) : null}

      {widgets.length === 0 ? (
        <div data-ds="" className="flex-col-gap-3 items-start">
          <p>No widgets yet. Add your first widget to start building.</p>
          <Button onClick={() => setShowAdd(true)}>Add widget</Button>
        </div>
      ) : (
        <CardList layout="grid">
          {widgets.map((w) => (
            <div key={w.id} data-ds="" style={{ gridColumn: sizeSpan[w.size] || 'span 6' }}>
              <Card>
                <div data-ds="" className="flex-row-gap-2 items-center">
                  {editing && editWTitle === w.id ? (
                    <>
                      <Input aria-label="Widget title" value={wTitleDraft} onChange={setWTitleDraft} autoComplete="off" error={wTitleErr} />
                      <IconButton tooltip="Save" onClick={() => handleWTitle(w)}><Check /></IconButton>
                      <IconButton tooltip="Cancel" onClick={() => setEditWTitle(null)}><X /></IconButton>
                    </>
                  ) : (
                    <>
                      <h3>{w.title || w.type.charAt(0).toUpperCase() + w.type.slice(1)}</h3>
                      {editing ? <IconButton tooltip="Edit title" onClick={() => { setEditWTitle(w.id); setWTitleDraft(w.title || ''); setWTitleErr(undefined); }}><Pencil /></IconButton> : null}
                    </>
                  )}
                  {editing ? (
                    <>
                      <IconButton tooltip={widgets.length === 1 ? 'Add another widget to reorder' : 'Move up'} disabledWithReason={widgets.length === 1 ? 'Add another widget to reorder' : undefined} onClick={() => handleMove(w, -1)}><ChevronUp /></IconButton>
                      <IconButton tooltip={widgets.length === 1 ? 'Add another widget to reorder' : 'Move down'} disabledWithReason={widgets.length === 1 ? 'Add another widget to reorder' : undefined} onClick={() => handleMove(w, 1)}><ChevronDown /></IconButton>
                      <Dropdown menu={<><Dropdown.Item onSelect={async () => { await repositionWidget(w.id, { size: 'small' } as never); flash(); }}>Small</Dropdown.Item><Dropdown.Item onSelect={async () => { await repositionWidget(w.id, { size: 'medium' } as never); flash(); }}>Medium</Dropdown.Item><Dropdown.Item onSelect={async () => { await repositionWidget(w.id, { size: 'large' } as never); flash(); }}>Large</Dropdown.Item></>}>
                        <IconButton tooltip="Size"><Settings /></IconButton>
                      </Dropdown>
                      <IconButton tooltip="Remove" onClick={() => setRemId(w.id)}><Trash2 /></IconButton>
                    </>
                  ) : null}
                </div>
                {w.type === 'note' ? <NoteWidget widget={w} dashboardId={dashboardId} onSaved={flash} /> : null}
                {w.type === 'counter' ? <CounterWidget widget={w} dashboardId={dashboardId} onSaved={flash} /> : null}
                {w.type === 'checklist' ? <ChecklistWidget widget={w} onSaved={flash} /> : null}
                {w.type === 'link_list' ? <LinkListWidget widget={w} onAdd={() => { setEditLinkW(w); setEditLinkIdx(null); setLTitle(''); setLUrl(''); setLErr(undefined); }} onEdit={(idx) => { setEditLinkW(w); setEditLinkIdx(idx); setLTitle(w.linkTitle?.[idx] || ''); setLUrl(w.linkUrl?.[idx] || ''); setLErr(undefined); }} /> : null}
              </Card>
            </div>
          ))}
        </CardList>
      )}

      {showDelete ? <DeleteDashboardDialog dashboardId={dashboard.id} dashboardName={dashboard.name} open={showDelete} onOpenChange={setShowDelete} onDeleted={() => router.push('/dashboards')} /> : null}

      <Dialog title="Add widget" open={showAdd} onOpenChange={setShowAdd} footer={(close) => <><Button onClick={() => close()}>Cancel</Button><Button onClick={handleCreate} loading={nPending} loadingWithReason="Creating widget">Create</Button></>}>
        <div data-ds="" className="flex-col-gap-3">
          <Select label="Type" value={nType} onChange={setNType}><SelectOption value="note" label="Note" /><SelectOption value="counter" label="Counter" /><SelectOption value="checklist" label="Checklist" /><SelectOption value="link_list" label="Link list" /></Select>
          <Input label="Title" value={nTitle} onChange={setNTitle} autoComplete="off" />
          <Select label="Size" value={nSize} onChange={setNSize}><SelectOption value="small" label="Small" /><SelectOption value="medium" label="Medium" /><SelectOption value="large" label="Large" /></Select>
          {nErr ? <p role="alert">{nErr}</p> : null}
        </div>
      </Dialog>

      <Dialog title="Remove this widget?" open={!!remId} onOpenChange={(o) => !o && setRemId(null)} footer={(close) => <><Button onClick={() => close()}>Cancel</Button><Button
                // destructive confirm removes widget permanently
                variant="danger"
                onClick={handleRemoveW}
                loading={remPending}
                loadingWithReason="Removing widget"
              >Remove</Button></>}>
        <p>This will permanently delete the widget and its contents. This cannot be undone.</p>
      </Dialog>

      <Dialog title={editLinkIdx !== null ? 'Edit link' : 'Add link'} open={!!editLinkW} onOpenChange={(o) => !o && setEditLinkW(null)} footer={(close) => <><Button onClick={() => close()}>Cancel</Button><Button onClick={async () => {
        if (lPending) return;
        if (!lTitle.trim() || lTitle.length > 80 || !lUrl.trim() || !/^https?:\/\//.test(lUrl)) { setLErr('Title is required max 80 and URL must be valid http/https'); return; }
        if (!editLinkW) return; setLPending(true);
        try {
          if (editLinkIdx !== null) { const nt = [...(editLinkW.linkTitle || [])]; const nu = [...(editLinkW.linkUrl || [])]; nt[editLinkIdx] = lTitle; nu[editLinkIdx] = lUrl; await updateLink(editLinkW.id, { linkTitle: nt, linkUrl: nu } as never); }
          else { await addLink(editLinkW.id, { linkTitle: [...(editLinkW.linkTitle || []), lTitle], linkUrl: [...(editLinkW.linkUrl || []), lUrl] } as never); }
          await updateDashboard(dashboardId, { lastEditedAt: new Date().toISOString() }); flash(); toast({ title: 'Link saved' }); setEditLinkW(null);
        } catch { setLErr('Could not save link. Try again.'); } finally { setLPending(false); }
      }} loading={lPending} loadingWithReason="Saving link">Save</Button></>}>
        <div data-ds="" className="flex-col-gap-3">
          <Input label="Link title" value={lTitle} onChange={setLTitle} autoComplete="off" />
          <Input label="Link URL" value={lUrl} onChange={setLUrl} autoComplete="off" placeholder="https://" />
          {lErr ? <p role="alert">{lErr}</p> : null}
        </div>
      </Dialog>
    </>
  );
}

